export class AIEngine {
  private boardState: BoardState;

  constructor(boardState: BoardState) {
    this.boardState = boardState;
  }

  private minimax(depth: number, isMaximizing: boolean, alpha: number, beta: number): number {
    const result = this.boardState.simulateMove(null);
    if (depth === 0 || result.isTerminal) {
      return result.heuristicValue;
    }

    if (isMaximizing) {
      let best = -Infinity;
      for (const move of this.boardState.getLegalMoves()) {
        this.boardState.makeMove(move);
        const eval = this.minimax(depth - 1, false, alpha, beta);
        this.boardState.undoMove(move);
        best = Math.max(best, eval);
        alpha = Math.max(alpha, eval);
        if (beta <= alpha) break;
      }
      return best;
    } else {
      let best = Infinity;
      for (const move of this.boardState.getLegalMoves()) {
        this.boardState.makeMove(move);
        const eval = this.minimax(depth - 1, true, alpha, beta);
        this.boardState.undoMove(move);
        best = Math.min(best, eval);
        beta = Math.min(beta, eval);
        if (beta <= alpha) break;
      }
      return best;
    }
  }

  public async generateMove(): Promise<Move> {
    const legalMoves = this.boardState.getLegalMoves();
    if (legalMoves.length === 0) return { from: '', to: '' };

    let bestMove: Move = { from: '', to: '' };
    let bestValue = -Infinity;
    for (const move of legalMoves) {
      this.boardState.makeMove(move);
      const value = this.minimax(3, false, -Infinity, Infinity);
      this.boardState.undoMove(move);
      if (value > bestValue) {
        bestMove = move;
        bestValue = value;
      }
    }
    return bestMove;
  }
}

